"""Saving a recording's note, and ``notes.txt``: every note in an Experiment, in one file a
person can read without the app."""

from __future__ import annotations

from datetime import datetime
from pathlib import Path

from pyrpoc.core.recording import Recording

from .format import RecordingError, read_json, read_record, recordings_in, write_json, write_text
from .grouping import program_display_name

NOTES_FILE = "notes.txt"
NOTES_FILE_HEADER = (
    "Generated by pyrpoc from the notes saved with each recording in this folder.\n"
    "Edits made here are overwritten: edit a note in the app's Data Library instead."
)


def save_note(recording: Recording) -> None:
    """Write ``recording``'s note where it is saved: into its metadata file once it is
    finished, and into its Experiment's ``notes.txt``."""
    # A recording still going writes its note itself the next time its saver writes.
    if recording.location is None:
        return
    if recording.finished:
        write_note(recording.location, recording.note)
    write_folder_notes(recording.location, recording)


def write_note(meta_path: Path, note: str) -> None:
    # Edited as raw JSON, so fields this version does not know survive.
    raw = read_json(meta_path)
    raw["notes"] = note
    write_json(meta_path, raw)


def write_folder_notes(meta_path: Path, edited: Recording) -> None:
    """Rebuild ``notes.txt`` beside ``meta_path`` from the notes of the recordings there,
    oldest first, taking ``edited``'s note as it is now; with no notes, there is no file."""
    # Rebuilt from disk every time, so it never holds duplicates or falls out of step. The
    # edited recording's own file may not hold its note yet while it runs.
    entries = sorted(
        (started_at, note_entry(started_at, name, program_key, note))
        for started_at, name, program_key, note in folder_notes(meta_path, edited)
        if note.strip()
    )
    path = meta_path.parent / NOTES_FILE
    if not entries:
        path.unlink(missing_ok=True)
        return
    write_text(path, "\n\n".join([NOTES_FILE_HEADER, *(entry for _, entry in entries)]) + "\n")


def folder_notes(meta_path: Path, edited: Recording) -> list[tuple[str, str, str, str]]:
    """When each recording beside ``meta_path`` started, its name, program and note."""
    notes = [(edited.started_at, edited.name, edited.program_key, edited.note)]
    for each in recordings_in(meta_path.parent):
        if each == meta_path:
            continue
        # A broken recording is reported when it is opened; it must not stop the others.
        try:
            record = read_record(each)
        except RecordingError:
            continue
        notes.append((record.started_at, record.name, record.program_key, record.notes))
    return notes


def note_entry(started_at: str, name: str, program_key: str, note: str) -> str:
    """One recording's entry: when it was taken, its name and program, then its note."""
    when = datetime.fromisoformat(started_at).astimezone().strftime("%Y-%m-%d %H:%M")
    heading = f"{when}  {name or program_key}  ({program_display_name(program_key)})"
    body = "\n".join(f"    {line}" for line in note.strip().splitlines())
    return f"{heading}\n{body}"
